from common import *

lessons=[]
def add(*a,**kw):
    item=card(*a,**kw);lessons.append(item);return item

def equivalents(item,*values):
    item['answer']['accepted']=list(dict.fromkeys(sum((acc(v) for v in values),[])))

def foot(p,a,b):
    v=[b[i]-a[i] for i in range(2)]
    t=sum((p[i]-a[i])*v[i] for i in range(2))/sum(x*x for x in v)
    return tuple(a[i]+t*v[i] for i in range(2))

def iso(base,height,show_height=False):
    p={'A':(-base/2,0),'B':(base/2,0),'C':(0,height),'H':(0,0)}
    edges=[['A','B'],['B','C'],['C','A']]
    if show_height:edges.append(['C','H'])
    return model(p,edges,['A','B','C']+(['H'] if show_height else []),{
        'focus':{'label':'Боковые стороны и основание','segments':[['A','C'],['B','C'],['A','B']]},
        'height':{'label':'Высота CH делит основание пополам','segments':[['C','H'],['A','H'],['H','B']],'points':['H']},
        'half':{'label':'Прямоугольный треугольник ACH','polygon':['A','C','H'],'points':['H']}})

def equi(side,show_height=False):return iso(side,side*math.sqrt(3)/2,show_height)

radical_goal='Искомая величина; корень записывай как sqrt(...).'

