    alpha=(180-vertex)/2;exterior=180-alpha
    m=iso(8,4*math.tan(math.radians(alpha)))
    m['points']['E']=[-7,0,0];m['edges'].append(['A','E']);m['labelNames'].append('E')
    m['views'].update({'base':{'label':'Равные углы при основании AB','segments':[['C','A'],['A','B'],['B','C']]},'external':{'label':'Внешний угол EAC','segments':[['A','E'],['A','C']]}})
    add('1.2','A',2,part,9,'Внешний угол равнобедренного треугольника',f'Найдите внешний угол при вершине A треугольника ABC, если AC = BC, а угол ACB равен {vertex}°.','Внешний угол при A (градусы).',fmt(exterior),'Сначала найди два равных угла при основании AB, затем смежный угол.',[
        step('Сумма углов при основании',f'∠A + ∠B = 180° − {vertex}° = {180-vertex}°.','Сумма углов треугольника равна 180°.','base'),
        step('Один угол при основании',f'AC = BC, поэтому ∠A = ∠B = {180-vertex}°/2 = {fmt(alpha)}°.','В равнобедренном треугольнике углы при основании равны.','base',accepted=fmt(alpha)),
        step('Внешний угол',f'∠EAC = 180° − {fmt(alpha)}° = {fmt(exterior)}°.','AE продолжает BA за A; внутренний и внешний углы смежные.','external',accepted=fmt(exterior))],m,'E лежит на продолжении BA за A. На рисунке видны обе стороны искомого внешнего угла; его величина не подписана.')

