def equi_named(height,second):
    side=2*height/math.sqrt(3)
    p={'A':(0,height),'B':(-side/2,0),'C':(side/2,0),'H':(0,0),
       'M':(side/4,height/2),'K':(-side/4,height/2),'O':(0,height/3)}
    target=['B','M'] if second=='M' else ['C','K']
    return model(p,[['A','B'],['B','C'],['C','A'],['A','H'],target],['A','B','C','H',second],{
        'focus':{'label':'Высота AH и второй заданный отрезок','segments':[['A','H'],target]},
        'same':{'label':'Высоты к равным сторонам','segments':[['A','H'],target]},
        'inner':{'label':'Треугольник с вершиной O','segments':[['A','O'],['O',target[0]],['A',target[0]]],'points':['O']},
        'angle':{'label':'Меньший угол между прямыми','segments':[['O','A'],['O',second]],'points':['O']}})

