    m=model(p,[['O','_b1'],['O','_b2'],['_a1','_a2'],['_b1','_b2']],['O','A','B'],{
        'focus':{'label':'Два экрана в одном световом пучке','segments':[['_a1','_a2'],['_b1','_b2']]},
        'distances':{'label':'Расстояния до параллельных экранов','segments':[['O','A'],['O','B']]},
        'large':{'label':'Большой экран ровно перекрывает высоту пучка','segments':[['O','_b1'],['O','_b2'],['_b1','_b2']]}})
