# B1. The two equal altitudes correspond to the equal sides.
for part,h,H in [('a',3,6),('b',4,10)]:
    base=2*H*h/math.sqrt(4*H*H-h*h)
    m=iso(base,H,True);p=m['points']
    p['P']=[*foot(p['A'],p['B'],p['C']),0];p['Q']=[*foot(p['B'],p['A'],p['C']),0]
    m['edges'] += [['A','P'],['B','Q']];m['labelNames'] += ['P','Q']
    m['views']['altitudes']={'label':'Три данные высоты CH, AP и BQ','segments':[['C','H'],['A','P'],['B','Q']]}
    text='Найдите основание равнобедренного треугольника, если его высоты равны 3, 3 и 6.' if part=='a' else 'Найдите площадь равнобедренного треугольника, если его высоты равны 4, 4 и 10.'
    result='4sqrt(15)/5' if part=='a' else '25sqrt(6)/3'
    steps=[
        step('Какая высота идёт к основанию?',f'Равным боковым сторонам соответствуют равные высоты {h} и {h}. Значит, высота CH к основанию AB равна {H}.','Из S = сторона · соответствующая высота/2 следует: равным сторонам соответствуют равные высоты. Все три высоты не равны, поэтому треугольник не равносторонний.','altitudes'),
        step('Сравниваем сторону и основание',f'Пусть AB = b, AC = BC = l. Из b · {H}/2 = l · {h}/2 получаем '+('l = 2b.' if part=='a' else 'l = 5b/2.'),'Одна площадь выражена через основание и через боковую сторону.','altitudes'),
        step('Пифагор для половины',f'AH = b/2, CH = {H}; l² = b²/4 + {H*H}.','Высота к основанию равнобедренного треугольника делит его пополам.','half'),
        step('Уравнение для основания','4b² = b²/4 + 36; 15b²/4 = 36; b² = 48/5.' if part=='a' else '25b²/4 = b²/4 + 100; 6b² = 100; b² = 50/3.','Подставляем выражение l через b и собираем слагаемые с b².','half'),
        step('Положительная длина','b = √(48/5) = 4√15/5.' if part=='a' else 'b = √(50/3) = 5√6/3.','Длина положительна; преобразования радикала сохраняют значение.','height')]
    if part=='b':steps.append(step('Площадь','S = b · 10/2 = 5 · (5√6/3) = 25√6/3.','Подставляем найденное основание и данную высоту.','half'))
    c=add('1.2','B',1,part,11,'Треугольник по трём высотам',text,('Основание' if part=='a' else 'Площадь')+'; корень записывай как sqrt(...).',result,'Равные высоты соответствуют равным сторонам. Сравни две формулы одной площади.',steps,m,'Все три данные высоты видимы сразу. CH проведена к основанию AB, AP и BQ — к боковым сторонам. В печати второй вариант B1 снова помечен «а)»; здесь он последовательно обозначен «б)».' if part=='b' else 'Все три данные высоты видимы сразу. CH проведена к основанию AB, AP и BQ — к боковым сторонам.')
    equivalents(c,*(['4sqrt(15)/5','4*sqrt(15)/5','sqrt(48/5)'] if part=='a' else ['25sqrt(6)/3','25*sqrt(6)/3','50/sqrt(6)']))

# C1. A proposition diagram avoids disclosing the shape before its proof.
for part,limit,known,small in [('a',132,80,50),('b',126,70,55)]:
    bound=180-limit;other=180-2*known
    m=model({'1':(0,0),'2':(2,0),'3':(4,0),'4':(6,0),'_bound':(3,-1)},[['1','2'],['2','3'],['3','4']],['1','2','3','4'],{
        'focus':{'label':'Проверяем четыре утверждения','points':['1','2','3','4']},
        'bound':{'label':'Что означает утверждение 3','points':['3','_bound']},
        'conflict':{'label':'Утверждения 2 и 3 несовместимы','points':['2','3']},
        'false':{'label':'Утверждение 2 оказалось ложным','points':['2']},
        'true':{'label':'Истинны утверждения 1,3,4','points':['1','3','4']}})
    m['labels']={'_bound':f'Каждый угол > {bound}°'}
    text=f'Найдите углы треугольника ABC, если из следующих четырёх утверждений о нём три истинны, а одно ложно: 1) треугольник ABC — равнобедренный; 2) треугольник ABC — прямоугольный; 3) сумма двух любых углов треугольника ABC меньше {limit}°; 4) один из углов треугольника ABC равен {known}°.'
    add('1.2','C',1,part,12,'Три истинных утверждения',text,'Углы по возрастанию через точку с запятой.',f'{small};{small};{known}','Условие о любых двух углах равносильно нижней границе для каждого третьего угла.',[
        step('Переписываем утверждение 3',f'Сумма двух углов равна 180° минус третий. Поэтому утверждение 3 означает: каждый угол больше 180° − {limit}° = {bound}°.','Вычитаем неравенство из 180°; требование выполняется для каждой пары.','bound'),
        step('Допустим, треугольник прямоугольный',f'Его острые углы в сумме дают 90°, так что хотя бы один из них не больше 45°. Он не может быть больше {bound}°. Следовательно, при истинном утверждении 2 утверждение 3 ложно.','Два числа, оба большие 45°, имеют сумму больше 90°.','conflict'),
        step('Получаем противоречие',f'Если единственно ложным было бы утверждение 3, то 1 и 4 были бы истинны. Равнобедренный прямоугольный треугольник имеет углы 45°, 45°, 90°, среди которых нет {known}°. Значит, предположение об истинности 2 неверно.','По условию ложно ровно одно утверждение.','false'),
        step('Две возможности равнобедренного треугольника',f'Итак,2 ложно, а 1,3,4 истинны. Если {known}° — угол при вершине, остальные равны(180° − {known}°)/2 = {small}°. Если это угол при основании, получаем {known}°, {known}°, {other}°.','В равнобедренном треугольнике равны два угла при основании.','true'),
        step('Проверяем оставшиеся условия',f'Второй набор не подходит: {other}° не больше {bound}°. В наборе {small}°, {small}°, {known}° каждый угол больше {bound}°, и прямого угла нет. Ответ: {small}°, {small}°, {known}°.','Проверяем именно три истинных утверждения и единственное ложное.','true')],m,'Метки 1–4 обозначают утверждения из условия, а не вершины треугольника. Такая схема позволяет проверить логику, не подсказывая форму искомого треугольника.')

# C2. Keep signed distance geometry exact in the interior and exterior cases.
for part,da,db in [('a',1,7),('b',2,5)]:
    side=2*math.sqrt(19) if part=='a' else 2*math.sqrt(57)/3
    height=side*math.sqrt(3)/2;dx=side/8 if part=='a' else -2*side/3
    p={'A':(0,0),'B':(side,0),'C':(side/2,height),'D':(dx,0),'H':(side/2,0)}
    p['P']=foot(p['A'],p['D'],p['C']);p['Q']=foot(p['B'],p['D'],p['C'])
    v=(p['C'][0]-dx,height);p['_l1']=(dx-.22*v[0],-.22*v[1]);p['_l2']=(dx+1.2*v[0],1.2*v[1])
    edges=[['A','B'],['B','C'],['C','A'],['_l1','_l2'],['A','P'],['B','Q']]
    if part=='b':edges.append(['D','A'])
    m=model(p,edges,['A','B','C','D','P','Q'],{
        'focus':{'label':'Данные расстояния AP и BQ до прямой CD','segments':[['A','P'],['B','Q']]},
        'ratio':{'label':'Подобные прямоугольные треугольники APD и BQD','segments':[['A','P'],['P','D'],['D','A'],['B','Q'],['Q','D'],['D','B']]},
        'height':{'label':'Высота CH и прямоугольный треугольник CHD','segments':[['C','H'],['H','D'],['D','C']],'points':['H']},
        'areas':{'label':'Площадь ABC через части с общей стороной CD','segments':[['C','D']], 'polygon':['A','B','C']}})
    where='сторону AB' if part=='a' else 'продолжение стороны AB за точку A'
    text=f'Через вершину C равностороннего треугольника ABC проведена прямая, пересекающая {where}. Расстояния от вершин A и B до этой прямой равны соответственно {da} и {db}. Найдите сторону треугольника ABC.'
    steps=[
        step('Сравниваем два прямоугольных треугольника','D — пересечение прямой с AB; AP и BQ — данные перпендикуляры. △APD и △BQD подобны. '+('Их углы при D вертикальные.' if part=='a' else 'Их углы при D совпадают, поскольку лучи DA и DB совпадают.'),'У треугольников по одному прямому и ещё по одному равному углу.','ratio'),
        step('Положение D через сторону s','AD/DB = AP/BQ = 1/7. При AB = s имеем AD = s/8, DB = 7s/8.' if part=='a' else 'AD/DB = AP/BQ = 2/5. Поскольку DB = DA + AB, при AB = s получаем AD = 2s/3, DB = 5s/3.','Соответствующие стороны подобных треугольников пропорциональны; учитываем порядок точек на прямой.','ratio'),
        step('Вводим высоту равностороннего треугольника','H — середина AB, CH = s√3/2. '+('DH = AH − AD = s/2 − s/8 = 3s/8.' if part=='a' else 'DH = DA + AH = 2s/3 + s/2 = 7s/6.'),'Высота равностороннего треугольника является медианой; её длина следует из теоремы Пифагора.','height'),
        step('Длина CD','CD² = CH² + DH² = 3s²/4 + 9s²/64 = 57s²/64; CD = s√57/8.' if part=='a' else 'CD² = CH² + DH² = 3s²/4 + 49s²/36 = 19s²/9; CD = s√19/3.','CH ⟂ AB, а D и H лежат на AB; треугольник CHD прямоугольный.','height'),
        step('Та же площадь через расстояния до CD','S(ABC) = S(ACD) + S(BCD) = CD · (1 + 7)/2 = 4CD.' if part=='a' else 'S(ABC) = S(BCD) − S(ACD) = CD · (5 − 2)/2 = 3CD/2.','При D внутри AB складываем площади; при порядке D,A,B вычитаем меньший треугольник из большего. AP и BQ — высоты к общей стороне CD.','areas'),
        step('Уравнение для стороны','s²√3/4 = 4 · s√57/8. Делим на s > 0: s = 2√57/√3 = 2√19.' if part=='a' else 's²√3/4 = 3 · s√19/(2 · 3). Делим на s > 0: s = 2√19/√3 = 2√57/3.','Площадь равностороннего треугольника равна s²√3/4.','areas')]
    c=add('1.2','C',2,part,12,'Расстояния до пересекающей прямой',text,radical_goal,'2sqrt(19)' if part=='a' else '2sqrt(57)/3','Обозначь точку пересечения D и опусти данные перпендикуляры. Подобие даст положение D, а две формулы площади — сторону.',steps,m,'D и данные перпендикуляры AP, BQ показаны сразу; H — вспомогательная середина основания, которая появляется в решении. Порядок точек на прямой сохранён.')
    equivalents(c,*(['2sqrt(19)','2*sqrt(19)','sqrt(76)'] if part=='a' else ['2sqrt(57)/3','2*sqrt(57)/3','sqrt(76/3)']))

# C4. The named base is AC; AB = BC, not AC = BC.
for part,S1,S2,ratio_num,ratio_den,height_num,height_den,base_sq,result in [
    ('a',4,2.5,8,5,3,8,104/3,'2sqrt(78)/3'),
    ('b',12,6.5,24,13,5,24,888/5,'2sqrt(1110)/5')]:
    base=math.sqrt(base_sq);height=height_num*base/height_den;fraction=ratio_num/(ratio_num+ratio_den)
    p={'A':(0,0),'B':(base/2,height),'C':(base,0),'D':(fraction*base/2,fraction*height),'H':(base/2,0)}
    m=model(p,[['A','B'],['B','C'],['C','A'],['C','D']],['A','B','C','D'],{
        'focus':{'label':'Биссектриса CD и две данные части','segments':[['C','D']]},
        'first':{'label':'Треугольник ACD','polygon':['A','C','D']},
        'second':{'label':'Треугольник BCD','polygon':['B','C','D']},
        'ratio':{'label':'Части AD и DB одной боковой стороны','segments':[['A','D'],['D','B'],['C','D']]},
        'height':{'label':'Высота BH к основанию AC','segments':[['B','H'],['A','H'],['H','C']],'points':['H']},
        'whole':{'label':'Площадь всего треугольника ABC','polygon':['A','B','C']}})
    text=f'Биссектриса угла C равнобедренного треугольника ABC пересекает боковую сторону AB в точке D. Площади треугольников ACD и BCD равны соответственно {fmt(S1)} и {fmt(S2).replace(".",",")}. Найдите длину основания AC треугольника ABC.'
    steps=[
        step('Складываем площади',f'S(ABC) = {fmt(S1)} + {fmt(S2).replace(".",",")} = {fmt(S1+S2).replace(".",",")}.','CD делит треугольник ABC на ACD и BCD без перекрытия.','whole'),
        step('Отношение частей AB',f'AD/DB = S(ACD)/S(BCD) = {fmt(S1)}/{fmt(S2).replace(".",",")} = {ratio_num}/{ratio_den}.','У двух треугольников общая высота из C к прямой AB; площади пропорциональны основаниям AD и DB.','ratio'),
        step('Используем биссектрису',f'AD/DB = AC/BC. Обозначим AC = b; тогда BC = {ratio_den}b/{ratio_num}.','Биссектриса делит противоположную сторону в отношении прилежащих сторон. Основание равно AC, поэтому AB = BC.','ratio'),
        step('Высота через основание',f'BH ⟂ AC, H — середина AC. BH² = BC² − HC² = ({ratio_den}b/{ratio_num})² − (b/2)² = '+('9b²/64.' if part=='a' else '25b²/576.')+f' Значит, BH = {height_num}b/{height_den}.','Высота к основанию равнобедренного треугольника является медианой; далее применяем теорему Пифагора.','height'),
        step('Уравнение площади','S = b · (3b/8)/2 = 3b²/16 = 13/2. Поэтому b² = 104/3.' if part=='a' else 'S = b · (5b/24)/2 = 5b²/48 = 37/2. Поэтому b² = 888/5.','Приравниваем площадь через основание и высоту сумме двух заданных площадей.','whole'),
        step('Длина основания','AC = √(104/3) = 2√78/3.' if part=='a' else 'AC = √(888/5) = 2√1110/5.','Берём положительный квадратный корень, поскольку ищем длину.','height')]
    c=add('1.2','C',4,part,13,'Основание через биссектрису и площади',text,'Длина AC; корень записывай как sqrt(...).',result,'Сравни площади через основания AD и DB, затем используй теорему о биссектрисе.',steps,m,'Основание — AC, равные боковые стороны — AB и BC. CD видна сразу; высота BH появляется только в соответствующем шаге.')
    equivalents(c,*([result,'2*sqrt(78)/3','sqrt(104/3)'] if part=='a' else [result,'2*sqrt(1110)/5','sqrt(888/5)']))

assert len(lessons)==26
assert len({(c['level'],c['number'],c['part']) for c in lessons})==26
for c in lessons:
    assert len(c['steps'])>=3
    assert all(s['view'] in c['model']['views'] for s in c['steps'])
    assert all(len(p)==3 and all(math.isfinite(x) for x in p) for p in c['model']['points'].values())
